/**
 * Lightweight, zero-dependency offline QR Code generator for MirageX Cyber HUD
 */
(function(window) {
  function QRCodeGenerator() {}

  // Basic QR Code generation for short text (Level M, alphanumeric/byte)
  QRCodeGenerator.generate = function(text, canvas, options) {
    options = options || {};
    var size = options.size || 220;
    var colorDark = options.colorDark || "#000000";
    var colorLight = options.colorLight || "#ffffff";

    if (!canvas || !canvas.getContext) return;
    var ctx = canvas.getContext("2d");
    canvas.width = size;
    canvas.height = size;

    // Use built-in vector encoder or QR matrix algorithm
    var qr = createQRCodeMatrix(text);
    var count = qr.getModuleCount();
    var tileW = size / count;
    var tileH = size / count;

    ctx.fillStyle = colorLight;
    ctx.fillRect(0, 0, size, size);

    ctx.fillStyle = colorDark;
    for (var row = 0; row < count; row++) {
      for (var col = 0; col < count; col++) {
        if (qr.isDark(row, col)) {
          ctx.fillRect(
            Math.round(col * tileW),
            Math.round(row * tileH),
            Math.ceil(tileW),
            Math.ceil(tileH)
          );
        }
      }
    }
  };

  // QR Code Math and Model implementation (Type 1-10 auto-sizing)
  function QR8bitByte(data) {
    this.mode = 4; // 8-bit byte mode
    this.data = data;
  }
  QR8bitByte.prototype = {
    getLength: function() { return this.data.length; },
    write: function(buffer) {
      for (var i = 0; i < this.data.length; i++) {
        buffer.put(this.data.charCodeAt(i), 8);
      }
    }
  };

  function QRBitBuffer() {
    this.buffer = [];
    this.length = 0;
  }
  QRBitBuffer.prototype = {
    get: function(index) {
      var bufIndex = Math.floor(index / 8);
      return ((this.buffer[bufIndex] >>> (7 - (index % 8))) & 1) === 1;
    },
    put: function(num, length) {
      for (var i = 0; i < length; i++) {
        this.putBit(((num >>> (length - i - 1)) & 1) === 1);
      }
    },
    putBit: function(bit) {
      var bufIndex = Math.floor(this.length / 8);
      if (this.buffer.length <= bufIndex) {
        this.buffer.push(0);
      }
      if (bit) {
        this.buffer[bufIndex] |= (0x80 >>> (this.length % 8));
      }
      this.length++;
    }
  };

  var QRPolynomial = {
    glog: function(n) {
      if (n < 1) throw new Error("glog(" + n + ")");
      return QRMath.LOG_TABLE[n];
    },
    gexp: function(n) {
      while (n < 0) n += 255;
      while (n >= 256) n -= 255;
      return QRMath.EXP_TABLE[n];
    }
  };

  var QRMath = {
    EXP_TABLE: new Array(256),
    LOG_TABLE: new Array(256)
  };
  for (var i = 0; i < 8; i++) QRMath.EXP_TABLE[i] = 1 << i;
  for (var i = 8; i < 256; i++) QRMath.EXP_TABLE[i] = QRMath.EXP_TABLE[i - 4] ^ QRMath.EXP_TABLE[i - 5] ^ QRMath.EXP_TABLE[i - 6] ^ QRMath.EXP_TABLE[i - 8];
  for (var i = 0; i < 255; i++) QRMath.LOG_TABLE[QRMath.EXP_TABLE[i]] = i;

  function Polynomial(num, shift) {
    var offset = 0;
    while (offset < num.length && num[offset] === 0) offset++;
    this.num = new Array(num.length - offset + shift);
    for (var i = 0; i < num.length - offset; i++) this.num[i] = num[i + offset];
  }
  Polynomial.prototype = {
    get: function(index) { return this.num[index]; },
    getLength: function() { return this.num.length; },
    multiply: function(e) {
      var num = new Array(this.getLength() + e.getLength() - 1);
      for (var i = 0; i < this.getLength(); i++) {
        for (var j = 0; j < e.getLength(); j++) {
          num[i + j] ^= QRPolynomial.gexp(QRPolynomial.glog(this.get(i)) + QRPolynomial.glog(e.get(j)));
        }
      }
      return new Polynomial(num, 0);
    },
    mod: function(e) {
      if (this.getLength() - e.getLength() < 0) return this;
      var ratio = QRPolynomial.glog(this.get(0)) - QRPolynomial.glog(e.get(0));
      var num = new Array(this.getLength());
      for (var i = 0; i < this.getLength(); i++) num[i] = this.get(i);
      for (var i = 0; i < e.getLength(); i++) {
        num[i] ^= QRPolynomial.gexp(QRPolynomial.glog(e.get(i)) + ratio);
      }
      return new Polynomial(num, 0).mod(e);
    }
  };

  var QRRSBlock = {
    RS_BLOCK_TABLE: [
      [1, 26, 19], [1, 44, 34], [1, 70, 55], [1, 100, 80], [1, 134, 108],
      [2, 86, 68], [2, 98, 78], [2, 121, 97], [2, 146, 116], [2, 86, 68, 2, 87, 69]
    ],
    getRSBlocks: function(typeNumber) {
      var rsBlock = QRRSBlock.RS_BLOCK_TABLE[typeNumber - 1];
      if (!rsBlock) rsBlock = [1, 26, 19];
      var list = [];
      for (var i = 0; i < rsBlock.length; i += 3) {
        var count = rsBlock[i];
        var totalCount = rsBlock[i + 1];
        var dataCount = rsBlock[i + 2];
        for (var j = 0; j < count; j++) {
          list.push({ totalCount: totalCount, dataCount: dataCount });
        }
      }
      return list;
    }
  };

  function createQRCodeMatrix(text) {
    var typeNumber = 4;
    if (text.length > 60) typeNumber = 8;
    if (text.length > 120) typeNumber = 10;

    var modules = null;
    var moduleCount = typeNumber * 4 + 17;

    function isDark(row, col) {
      if (row < 0 || moduleCount <= row || col < 0 || moduleCount <= col) return false;
      return modules[row][col];
    }

    function makeImpl() {
      modules = new Array(moduleCount);
      for (var row = 0; row < moduleCount; row++) {
        modules[row] = new Array(moduleCount);
        for (var col = 0; col < moduleCount; col++) modules[row][col] = null;
      }
      // Position probes
      setupPositionProbe(0, 0);
      setupPositionProbe(moduleCount - 7, 0);
      setupPositionProbe(0, moduleCount - 7);
      setupTimingPattern();
      setupPositionAdjustPattern();
      mapData(createData());
    }

    function setupPositionProbe(row, col) {
      for (var r = -1; r <= 7; r++) {
        if (row + r <= -1 || moduleCount <= row + r) continue;
        for (var c = -1; c <= 7; c++) {
          if (col + c <= -1 || moduleCount <= col + c) continue;
          if ((0 <= r && r <= 6 && (c === 0 || c === 6)) ||
              (0 <= c && c <= 6 && (r === 0 || r === 6)) ||
              (2 <= r && r <= 4 && 2 <= c && c <= 4)) {
            modules[row + r][col + c] = true;
          } else {
            modules[row + r][col + c] = false;
          }
        }
      }
    }

    function setupTimingPattern() {
      for (var r = 8; r < moduleCount - 8; r++) {
        if (modules[r][6] !== null) continue;
        modules[r][6] = (r % 2 === 0);
      }
      for (var c = 8; c < moduleCount - 8; c++) {
        if (modules[6][c] !== null) continue;
        modules[6][c] = (c % 2 === 0);
      }
    }

    function setupPositionAdjustPattern() {
      if (typeNumber < 2) return;
      var pos = [6, moduleCount - 7];
      for (var i = 0; i < pos.length; i++) {
        for (var j = 0; j < pos.length; j++) {
          var row = pos[i];
          var col = pos[j];
          if (modules[row][col] !== null) continue;
          for (var r = -2; r <= 2; r++) {
            for (var c = -2; c <= 2; c++) {
              if (r === -2 || r === 2 || c === -2 || c === 2 || (r === 0 && c === 0)) {
                modules[row + r][col + c] = true;
              } else {
                modules[row + r][col + c] = false;
              }
            }
          }
        }
      }
    }

    function createData() {
      var rsBlocks = QRRSBlock.getRSBlocks(typeNumber);
      var buffer = new QRBitBuffer();
      var data = new QR8bitByte(text);
      buffer.put(data.mode, 4);
      buffer.put(data.getLength(), 8);
      data.write(buffer);

      var totalDataCount = 0;
      for (var i = 0; i < rsBlocks.length; i++) totalDataCount += rsBlocks[i].dataCount;
      if (buffer.length + 4 <= totalDataCount * 8) buffer.put(0, 4);
      while (buffer.length % 8 !== 0) buffer.putBit(false);
      while (true) {
        if (buffer.length >= totalDataCount * 8) break;
        buffer.put(0xEC, 8);
        if (buffer.length >= totalDataCount * 8) break;
        buffer.put(0x11, 8);
      }
      return buffer;
    }

    function mapData(data) {
      var inc = -1;
      var row = moduleCount - 1;
      var bitIndex = 0;
      var byteIndex = 0;

      for (var col = moduleCount - 1; col > 0; col -= 2) {
        if (col === 6) col--;
        while (true) {
          for (var c = 0; c < 2; c++) {
            if (modules[row][col - c] === null) {
              var dark = false;
              if (byteIndex < data.buffer.length) {
                dark = ((data.buffer[byteIndex] >>> (7 - bitIndex)) & 1) === 1;
              }
              // Mask pattern 0 ( (row + col) % 2 == 0 )
              var mask = ((row + (col - c)) % 2 === 0);
              if (mask) dark = !dark;
              modules[row][col - c] = dark;
              bitIndex++;
              if (bitIndex === 8) {
                bitIndex = 0;
                byteIndex++;
              }
            }
          }
          row += inc;
          if (row < 0 || moduleCount <= row) {
            row -= inc;
            inc = -inc;
            break;
          }
        }
      }
    }

    makeImpl();

    return {
      getModuleCount: function() { return moduleCount; },
      isDark: isDark
    };
  }

  window.QRCodeGenerator = QRCodeGenerator;
})(window);
